class Solution {
public:
    string getSmallestString(string s) {
        for (int i = 0; i + 1 < (int)s.size(); i++)
            if (s[i] > s[i+1] && (s[i] - s[i+1]) % 2 == 0) {
                swap(s[i], s[i+1]);
                return s;
            }
        return s;
    }
};

