class Solution {
public:
    string getSmallestString(string s) {
        string best = s;
        for (int i = 0; i + 1 < (int)s.size(); i++) {
            if ((s[i] - s[i+1]) % 2 == 0) {
                string t = s;
                swap(t[i], t[i+1]);
                best = min(best, t);
            }
        }
        return best;
    }
};

