class Solution {
    public String getSmallestString(String s) {
        String best = s;
        for (int i = 0; i + 1 < s.length(); i++) {
            if ((s.charAt(i) - s.charAt(i+1)) % 2 == 0) {
                char[] t = s.toCharArray();
                char tmp = t[i]; t[i] = t[i+1]; t[i+1] = tmp;
                String c = new String(t);
                if (c.compareTo(best) < 0) best = c;
            }
        }
        return best;
    }
}

