    for (let i = 0; i + 1 < s.length; i++) {
        if ((s.charCodeAt(i) - s.charCodeAt(i+1)) % 2 === 0) {
            const t = s.slice(0, i) + s[i+1] + s[i] + s.slice(i+2);
